"OLAYLAR_ARKEOLOJI_PILOT:-5999-01-01:0":{"b": ["Li Girê Rojhilat ê Çatalhöyükê çalakiya niştecihbûnê dawî dibe", "d057cc52"], "d": ["56 dîrokên AMS: çalakî tavilê piştî B.Z. 6000 cal BC dawî dibe; goristina Neolîtîk çend dehsal şûnda qut dibe.", "9ba489f4"]},
"OLAYLAR_ARKEOLOJI_PILOT:-6999-01-01:0":{"b": ["Jiahu (Henan): niştecihbûn dest pê dike", "44236466"], "d": ["Niştecihbûneke sê qonaxî; seramîka beşa herî kevn di navbera B.Z. 7000–6600 de tê dîrokkirin.", "154087ed"]},
